from pathlib import Path
import json,re
event="1791199828-ba95049a4dc8"
base=Path.home()/".local/share/prediction-chat-bridge"
msg=None
where=None
for d in ("sent","inflight","outbox"):
    p=base/d/f"{event}.json"
    if p.is_file():
        obj=json.loads(p.read_text(encoding="utf-8",errors="replace"))
        msg=str(obj.get("message") or "")
        where=str(p)
        break
if msg is None:
    print("DIRTY_DETAIL=EVENT_MISSING",flush=True)
    raise SystemExit(2)

markers=["PRODUCTION_STAGED_INSPECT ","PRODUCTION_COMPARE_WORKTREE ","PRODUCTION_DIFF_INSPECT "]
out={"event_file":where,"staged":None,"worktree":None,"diffs":[]}
for line in msg.splitlines():
    for marker in markers:
        i=line.find(marker)
        if i>=0:
            raw=line[i+len(marker):].strip()
            try:
                obj=json.loads(raw)
            except Exception:
                continue
            if marker.startswith("PRODUCTION_STAGED"):
                out["staged"]=obj
            elif marker.startswith("PRODUCTION_COMPARE"):
                out["worktree"]=obj
            else:
                body=str(obj.get("diff") or "")
                paths=[]
                for m in re.finditer(r"^diff --git a/(.+?) b/(.+?)$",body,re.M):
                    paths.append(m.group(2))
                out["diffs"].append({
                    "mode":obj.get("mode"),
                    "chars_total":obj.get("chars_total"),
                    "truncated":obj.get("truncated"),
                    "paths":paths,
                    "tail":body[-12000:]
                })
print("DIRTY_DETAIL="+json.dumps(out,separators=(",",":"),sort_keys=True),flush=True)
raise SystemExit(0)
